head.script:
			
			var currIndex = 0;                                           // 현재 행 ( 그리드내에서 탭키 이벤트시 다음행으로 이동 처리)
			var divisionId= WebSquare.net.getParameter( "divisionId" );
			var divisionNm= decodeURIComponent(WebSquare.net.getParameter( "divisionNm" ));
			var tabIdx = WebSquare.net.getParameter( "tabIdx" );
			
			var existDt = "";
			var srchEndDt = "";
			var todayDD = "";

        /**************************************************************************
         * function    : init
         * Description : 서브 메인 화면 초기화
         * Parameter   : 
         * Return      : 
         **************************************************************************/
         function init() {
				this.document.title=divisionNm;
				resizeIframe();
				
				todayDD = WebSquare.date.getCurrentServerDate( "yyyyMMdd" );
				
				getExistMaxDate();
				
				//searchData1();
				
				grdMain.setColumnBackgroundColor( 0 , "#f2f6f7" );
				
				
			}
			
			function getExistMaxDate(){
				var BISCdtRnkCmpDTO = WebSquare.xml.indent(getInstanceNode("BISCdtRnkCmpDTO"));
		       	
		      callProFrameProcess("BIS-KOFIABOND","BISCdtRnkCmpSrchSO","getExistMaxDate",BISCdtRnkCmpDTO,"respDate");		
			}			
			
			
			function fnImageClick(data) {
				comFileDownload2(data);
			}
			function comFileDownload2(fileName) {
        	  	WebSquare.net.download( "/jsp/download2.jsp?"
					+"&fileName="+encodeURIComponent(WebSquare.text.BASE64Encoder(fileName)), "", "post" );
          	}
          	/**************************************************************************
			 * function    : custFileDownImgCol
			 * Description : grid cell에 다운로드 버튼 이미지 보여주기 (커스텀 포맷터 사용)
			 * Parameter   : data,formattedData,row,col (커스텀 포맷터 기본 인자값들)
			 * Return      : null
			 **************************************************************************/
			function custFileDownImgCol(data,formattedData,row,col){				  
				// 스트링 값을 읽어 파일다운 버튼 이미지 생성				 
				var str = "";			
				
				if (data.length > 0){				
					// 이미지 태그 생성
					str = str + '<img src="/images/btn/allfile.gif" style="cursor:pointer;"' + ' title="" onclick="fnImageClick(\''+data+'\');"/>';
				} 
								
				return str;
			}	        		
			
			
			/**************************************************************************
          * function    : callBack
          * Description : submission 실행 후 Callback
          * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
          * Return      : null
          **************************************************************************/
        	function callBack(svcId,fnId,strResp) {   
				
				
				if (svcId == "BISCdtRnkCmpSrchSO") {
					
					grdMain.setColumnVisible( 5 , true );
					grdMain.setColumnVisible( 6 , true );
					grdMain.setColumnVisible( 7 , true );

					if (fnId == "selectData") {
						
						grdMain.setXML( getInstanceNode("resp/root/message/BISCdtRnkCmpListDTO") );
						/*
						var radio1Val = radio1.getValue();	
						
						if(radio1Val == 1){
							grdMain.setColumnVisible( 7 , false );
							
						}else if(radio1Val == 2){
							grdMain.setColumnVisible( 2 , false );
							grdMain.setColumnVisible( 5 , false );
							grdMain.setColumnVisible( 7 , false );
							
						}else if(radio1Val == 4){
							grdMain.setColumnVisible( 5 , false );
						
						}else {
							grdMain.setColumnVisible( 2 , true );
							grdMain.setColumnVisible( 5 , false );
							grdMain.setColumnVisible( 6 , false );
							grdMain.setColumnVisible( 7 , false );
						}
						
						*/
	        			for(var i=0;i<grdMain.getRowCount();i++){
	        				/*
	        				if( (radio1Val != 2) || radio1Val != 3 ){
	        					data0 = grdMain.getCellData( i , 0 );
	        					data9 = grdMain.getCellData( i , "companyNm" ); //회사명(max)
	        					
        						if(data0.indexOf(data10.replace("(주)", ""))>0){
	        							
	        					
	        					} else {
	        						textData = data0 +"<br>("+data9+")";
	        						grdMain.setCellData( i , 0 ,textData);
	        					}
	        					
	        				}else {
	        					grdMain.setCellData( i , 0 ,data0);
	        					
	        				}
	        				*/
	        				
	        				
	        				
	        				var data2 = grdMain.getCellData( i , 2 );
	        				if(data2==""){
	        					grdMain.setCellData( i , 2 , "-");
	        				}
	        				
	        				var data3 = grdMain.getCellData( i , 3 );
	        				if(data3==""){
	        					grdMain.setCellData( i , 3 , "-");
	        				}
	        				
	        				var data4 = grdMain.getCellData( i , 4 );
	        				if(data4==""){
	        					grdMain.setCellData( i , 4 , "-");
	        				}
	        				
	        				var data5 = grdMain.getCellData( i , 5 );
	        				if(data5 ==""){
	        					grdMain.setCellData( i , 5 , "-");
	        				} 
	        				
	        				var data6 = grdMain.getCellData( i , "creditWatch" ); 
	        				var data8 = getValue("resp/root/message/BISCdtRnkCmpListDTO/BISCdtRnkCmpDTO[" + (i + 1) + "]/val1");
	        				/*
	        				한국신용평가	A15001    01
							한국기업평가	A10001    02
							한국신용정보	A15002    03
							서울신용정보	A15003    04
	        				*/
	        				
	        				if(data6==""){
	        					grdMain.setCellData( i , 6 , "-");
	        				} else if (data6 == "10" && data8 == "A15001") {
	        					grdMain.setCellData( i , 6 , "상향검토");
	        				} else if (data6 == "10" && (data8 == "A10001" || data8 == "A15003")) {
	        					grdMain.setCellData( i , 6 , "↑");
	        				} else if (data6 == "10" && data8 == "A15002") {
	        					grdMain.setCellData( i , 6 , "↑");
	        				} else if (data6 == "20" && data8 == "A15001") {
	        					grdMain.setCellData( i , 6 , "하향검토");
	        				} else if (data6 == "20" && (data8 == "A10001" || data8 == "A15003")) {
	        					grdMain.setCellData( i , 6 , "↓");
	        				} else if (data6 == "20" && data8 == "A15002") {
	        					grdMain.setCellData( i , 6 , "↓");
	        				} else if (data6 == "30" && data8 == "A15001") {
	        					grdMain.setCellData( i , 6 , "미확정검토");
	        				} else if (data6 == "30" && (data8 == "A10001" || data8 == "A15003")) {
	        					grdMain.setCellData( i , 6 , "↕");
	        				} else if (data6 == "30" && data8 == "A15002") {
	        					grdMain.setCellData( i , 6 , "◆");
	        				} else {
	        					grdMain.setCellData( i , 6 , "-");
	        				}
	        				
	        				var data7 = grdMain.getCellData( i , 7 );
	        				if(data7=="" || data7=="00"){
	        					grdMain.setCellData( i , 7 , "-");
							} else if(data7.substr(0,1)=="0" && data7.substr(1)!="0"){
	        					data7 = data7.substr(1);
	        					grdMain.setCellData( i , 7 , data7+"월");
	        				} else {
	        					grdMain.setCellData( i , 7 , data7+"월");
	        				}
	        				
	        			}		        			
		        		
		 				}else if( fnId == "getExistMaxDate"){
		 					existDt = getValue("respDate/root/message/BISCdtRnkCmpListDTO/BISCdtRnkCmpDTO[1]/standardDt"); 
		 					
		 					startDtDD.setValue( addMonth(existDt, -1) );
							endDtDD.setValue( existDt );
							
							searchData1();
		 				}
		 			}
		 			resizeIframe();
            }

        	
        	/**************************************************************************
         * function    : searchData1
         * Description : 신용등급 비교공시
         * Parameter   : null
         * Return      : null
         **************************************************************************/
        	function searchData1() {
        		
        		if ( isValidDate(startDtDD.getValue()) == false || isValidDate(endDtDD.getValue()) == false ) {
					showMsg("C_I029");
					return;
				}
				
				if  ( startDtDD.getValue() > endDtDD.getValue() ) {
					showMsg("C_I055");
					return;
				}
				/*
        		//WebSquare.ModelUtil.removeChildNodes( "BISCdtRnkCmpDTO" );
        		setValue("BISCdtRnkCmpDTO/inquiryStd", "1"); //발행기간별 조회구분 값(1)
        		
        		//setValue("BISCdtRnkCmpDTO/schField", radio1.getValue()); // 종류 
        		var tmpValue = radio1.getValue();
        		
        		if ( tmpValue == "1" || tmpValue == "2" || tmpValue == "4" ) {
        			setValue("BISCdtRnkCmpDTO/schField", tmpValue); // 종류
        		} else {
        			setValue("BISCdtRnkCmpDTO/schField", 3); // 종류
        			setValue("BISCdtRnkCmpDTO/val1", tmpValue - 4);
        		}
        		
        		if ( radio2.getValue() ) {
        			setValue("BISCdtRnkHotDTO/schData", "1");
        		}
        		
        		//setValue("BISCdtRnkCmpDTO/issueCompCd", search1.getValue()); //발행회사 코드
        		//setValue("BISCdtRnkCmpDTO/schData", radio2.getValue()); //조회범위 (추후 포함예정)
        		setValue("BISCdtRnkCmpDTO/standardDt1", startDtDD.getValue()); // 조회 시작일
        		setValue("BISCdtRnkCmpDTO/standardDt2", endDtDD.getValue()); // 조회 종료일		
		        //var BISCdtRnkCmpDTO =  {"BISCdtRnkCmpDTO":{}};
			
		       	//callProFrame("BIS-KOFIABOND", "BISCdtRnkCmpSrchSO","select", BISCdtRnkCmpDTO ,"BISCdtRnkCmpDTO","resp");
		       	var BISCdtRnkCmpDTO = WebSquare.xml.serialize(getInstanceNode("BISCdtRnkCmpDTO"));
		       	
		       	callProFrameProcess("BIS-KOFIABOND","BISCdtRnkCmpSrchSO","select",BISCdtRnkCmpDTO,"resp");
		      */
		      
        		
        		setValue("BISCdtRnkCmpDTO/inquiryStd", radio1.getValue());	//종류
        		setValue("BISCdtRnkCmpDTO/schField", radio2.getValue());		//조회범위
				
				setValue("BISCdtRnkCmpDTO/standardDt1", startDtDD.getValue()); // 조회 시작일
        		setValue("BISCdtRnkCmpDTO/standardDt2", endDtDD.getValue()); // 조회 종료일	
        		
        		setValue("BISCdtRnkCmpDTO/val10", "2");	//탭2 - 발행기간별	
        		
		      var BISCdtRnkCmpDTO = WebSquare.xml.indent(getInstanceNode("BISCdtRnkCmpDTO"));
		       	
		      callProFrameProcess("BIS-KOFIABOND","BISCdtRnkCmpSrchSO","selectData",BISCdtRnkCmpDTO,"resp");		       	
        	}

            
            
         /**************************************************************************
          * function    : excelDownLoad
          * Description : 그리드의 내용을 엑셀로 다운로드
          * Parameter   : null
          * Return      : null
          **************************************************************************/
         function excelDownLoad(removeCol) {
         	saveExcelDown(grdMain, divisionNm, "1", true, false, removeCol);
         }
         
         
